mapper.select:
/* com.portal.user.poll.qrm.QustnrRespondManageMapper.selectQustnrRespondManageList */ SELECT ( SELECT QUSTNR_SJ FROM LETTNQESTNRINFO WHERE QESTNR_ID = A.QESTNR_ID ) AS QESTNR_SJ, A.QESTNR_ID, A.QUSTNR_RESPOND_ID AS qestnrRespondId, A.SEXDSTN_CODE, A.OCCP_TY_CODE, A.RESPOND_NM, A.BRTHDY, A.AREA_NO, A.MIDDLE_TELNO, A.END_TELNO, A.QUSTNR_TMPLAT_ID AS qestnrTmplatId, A.FRST_REGIST_PNTTM AS frstRegisterPnttm, A.FRST_REGISTER_ID, (SELECT USER_NM FROM COMVNUSERMASTER WHERE ESNTL_ID = A.FRST_REGISTER_ID) AS FRST_REGISTER_NM, A.LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID FROM LETTNQUSTNRRESPONDINFO A WHERE 1=1
AND A.RESPOND_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.BRTHDY LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.poll.qrm.QustnrRespondManageMapper.selectQustnrRespondManageListCnt */ SELECT COUNT(*) AS totcnt FROM LETTNQUSTNRRESPONDINFO WHERE 1=1
AND RESPOND_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND BRTHDY LIKE CONCAT('%', #{searchKeyword}, '%')
